const menus = [{ icon: LayoutDashboard, text: '数据看板' }, { icon: Menu, text: '研学课程' }, { icon: ImagePlus, text: '托管活动管理' }, { icon: PlaySquare, text: '社会实践' }, { icon: MapPin, text: '场地管理' }, { icon: Users, text: '集体研学活动' }, { icon: Menu, text: '任务广场' }, { icon: MoreHorizontal, text: '比选中心' }, { icon: Settings2, text: '出行管理' }, { icon: LayoutDashboard, text: '报表管理(研学)' }, { icon: CircleHelp, text: '订单管理（研学）' }, { icon: CircleHelp, text: '财务管理（研学）' }, { icon: Menu, text: '托管活动结算' }]
const emptyConfig: LiveConfig = { name: '', time: '', address: '', cover: '', code: '' }

function UploadBox({ label, value, onChange, compact = false }: { label: string; value: string; onChange: (value: string) => void; compact?: boolean }) {
  const select = (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => onChange(String(reader.result)); reader.readAsDataURL(file) }
  return <div className={`web-upload ${compact ? 'qr' : ''}`}>{value ? <div className="web-preview"><img src={value} alt={`已上传的${label}`} /><button type="button" onClick={() => onChange('')}><X size={14} /></button></div> : <label><ImagePlus size={22} /><span>上传{label}</span><input type="file" accept="image/*" onChange={select} /></label>}<small>{compact ? '请上传直播二维码图片' : '建议上传 16:9 的图片'}</small></div>
}

function LiveModal({ activity, onClose, onSaved }: { activity: Activity; onClose: () => void; onSaved: () => void }) {
  const [form, setForm] = useState<LiveConfig>({ ...emptyConfig, name: `${activity.name}直播间` })
  const [errors, setErrors] = useState<Record<string, string>>({})
  const update = (key: keyof LiveConfig, value: string) => { setForm((current) => ({ ...current, [key]: value })); setErrors((current) => ({ ...current, [key]: '', stream: '' })) }
  const submit = () => { const next: Record<string, string> = {}; if (!form.name.trim()) next.name = '请输入直播间名称'; if (!form.cover) next.cover = '请上传直播间封面'; if (!form.time) next.time = '请选择开播时间'; if (!form.address.trim() && !form.code) next.stream = '直播地址和直播二维码至少填写一项'; setErrors(next); if (!Object.keys(next).length) onSaved() }
  return <div className="web-modal-mask" onMouseDown={onClose}><section className="web-modal" role="dialog" aria-modal="true" aria-label="直播设置" onMouseDown={(event) => event.stopPropagation()}><header><div><span className="modal-title-icon"><PlaySquare size={19} /></span><strong>直播设置</strong></div><button onClick={onClose} aria-label="关闭"><X size={21} /></button></header><div className="web-modal-content"><div className="selected-activity"><span>当前活动</span><strong>{activity.name}</strong><em>{activity.school}</em></div><div className="web-form-grid"><label><span>直播间名称 <b>*</b></span><input value={form.name} onChange={(event) => update('name', event.target.value)} placeholder="请输入直播间名称" />{errors.name && <i>{errors.name}</i>}</label><label><span>开播时间 <b>*</b></span><input type="datetime-local" value={form.time} onChange={(event) => update('time', event.target.value)} />{errors.time && <i>{errors.time}</i>}</label><div className="wide web-form-upload"><span>直播间封面 <b>*</b></span><UploadBox label="封面" value={form.cover} onChange={(value) => update('cover', value)} />{errors.cover && <i>{errors.cover}</i>}</div><label className="wide"><span>直播地址</span><input value={form.address} onChange={(event) => update('address', event.target.value)} placeholder="请输入直播推流地址" /></label><div className="wide web-form-upload"><span>直播二维码</span><UploadBox label="二维码" compact value={form.code} onChange={(value) => update('code', value)} />{errors.stream && <i>{errors.stream}</i>}</div></div></div><footer><button className="web-cancel" onClick={onClose}>取消</button><button className="web-primary" onClick={submit}>保存设置</button></footer></section></div>
}

