import { Building2, MonitorCog, Users } from 'lucide-react'
import { useLocation, useNavigate } from 'react-router-dom'

const clients = [
  { path: '/org-mini', label: '机构端小程序', icon: Building2 },
  { path: '/org-web', label: '机构 Web', icon: MonitorCog },
  { path: '/parent-mini', label: '家长小程序', icon: Users },
]

export default function ClientSwitcher() {
  const location = useLocation()
  const navigate = useNavigate()
  return <nav className="client-switcher" aria-label="用户端切换">{clients.map(({ path, label, icon: Icon }) => <button key={path} type="button" title={label} aria-current={location.pathname === path ? 'page' : undefined} className={`client-switcher__button ${location.pathname === path ? 'client-switcher__button--active' : ''}`} onClick={() => navigate(path)}><Icon size={15} /><span className="client-switcher__label">{label}</span></button>)}</nav>
}
