import { BookOpenText, ChevronLeft, ChevronRight, X } from 'lucide-react'
import { useState } from 'react'
import { useLocation } from 'react-router-dom'
import '../business-rules.css'

type Rule = { tag: string; title: string; content: string }

type RuleSet = { title: string; rules: Rule[] }

const ruleSets: Record<string, RuleSet> = {
  '/org-mini': {
    title: '直播间配置 - 业务规则',
    rules: [
      { tag: '配置流程', title: '创建直播间', content: '机构端在直播计划中创建直播间，依次维护基本信息、直播封面、开播时间和推流信息；创建成功后进入直播计划列表。' },
      { tag: '必填校验', title: '配置完整性', content: '直播间名称、直播封面和开播时间为必填项；直播地址与直播二维码至少填写一项，未满足条件时不可提交。' },
      { tag: '状态流转', title: '待开播状态', content: '新建直播间默认展示为待开播；直播计划与历史直播分栏展示，历史直播仅查看已结束内容。' },
      { tag: '交互规则', title: '时间与图片', content: '开播时间通过底部日期时间选择器确认；封面和二维码支持本地上传、预览和移除。' },
    ],
  },
  '/org-web': {
    title: '直播设置 - 业务规则',
    rules: [
      { tag: '操作入口', title: '按活动配置', content: '机构 Web 在出行管理活动列表中，针对单个活动点击“直播设置”进入配置；“查看”仅用于查看活动信息。' },
      { tag: '配置流程', title: '保存直播设置', content: '设置直播间名称、封面、开播时间及推流信息后保存；校验成功即提示保存成功，并关闭设置弹窗。' },
      { tag: '必填校验', title: '推流信息约束', content: '直播间名称、直播封面、开播时间必填；直播地址和直播二维码至少配置一个，二维码须为图片文件。' },
      { tag: '数据范围', title: '活动关联', content: '直播设置绑定当前活动，弹窗内展示活动名称和学校信息；不同活动分别维护各自的直播配置。' },
    ],
  },
  '/parent-mini': {
    title: '活动直播观看 - 业务规则',
    rules: [
      { tag: '观看入口', title: '活动直播间', content: '家长在已参与活动中点击“活动直播”进入直播间列表，可查看当前活动下全部可观看的直播间。' },
      { tag: '展示规则', title: '直播卡片信息', content: '每个直播间展示封面、名称、直播日期与直播状态；状态包括直播中和待开播，直播中优先展示。' },
      { tag: '观看方式', title: '二维码与跳转', content: '配置二维码的直播间点击后展示二维码，可保存至本地后使用微信扫码进入；直跳直播间点击后展示跳转确认提示。' },
      { tag: '状态约束', title: '观看提示', content: '待开播直播间仍可查看入口，但页面明确提示待开播状态；直播中直播间展示正在直播提示。' },
    ],
  },
}

function RuleItems({ rules }: { rules: Rule[] }) {
  return <>{rules.map((rule) => <article className="business-rules__item" key={rule.title}><span className="business-rules__tag">{rule.tag}</span><strong>{rule.title}</strong><p>{rule.content}</p></article>)}</>
}

export default function BusinessRules() {
  const { pathname } = useLocation()
  const [webCollapsed, setWebCollapsed] = useState(false)
  const [mobileOpen, setMobileOpen] = useState(false)
  const data = ruleSets[pathname] ?? ruleSets['/org-mini']

  if (pathname === '/org-web') {
    return <aside className={`business-rules business-rules--web ${webCollapsed ? 'business-rules--collapsed' : ''}`}>
      <button className="business-rules__header" type="button" onClick={() => setWebCollapsed((value) => !value)} aria-expanded={!webCollapsed}>
        <BookOpenText size={18} />
        <span className="business-rules__title">{data.title}</span>
        {webCollapsed ? <ChevronLeft size={18} /> : <ChevronRight size={18} />}
      </button>
      {!webCollapsed && <div className="business-rules__body"><RuleItems rules={data.rules} /></div>}
    </aside>
  }

  return <>
    <button className="business-rules__trigger" type="button" onClick={() => setMobileOpen(true)} aria-label="查看业务规则"><BookOpenText size={20} /></button>
    {mobileOpen && <div className="business-rules__modal" role="dialog" aria-modal="true" aria-label={data.title}>
      <button className="business-rules__mask" type="button" aria-label="关闭业务规则" onClick={() => setMobileOpen(false)} />
      <section className="business-rules__sheet">
        <header><div><BookOpenText size={18} /><strong>{data.title}</strong></div><button type="button" onClick={() => setMobileOpen(false)} aria-label="关闭"><X size={20} /></button></header>
        <div className="business-rules__body"><RuleItems rules={data.rules} /></div>
      </section>
    </div>}
  </>
}
