import { useState } from 'react'
import { ArrowLeft, BookOpen, CalendarDays, ChevronRight, CircleUserRound, Download, Image, MessageCircle, MoreHorizontal, Play, Tv, X } from 'lucide-react'

const waterfallCover = 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=majestic%20waterfall%20in%20a%20lush%20Chinese%20forest%2C%20rainbow%20over%20golden%20river%2C%20photorealistic%20travel%20photography%2C%20bright%20daylight%2C%20wide%20landscape&image_size=landscape_16_9'
const roomOneCover = 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=children%20outdoor%20nature%20education%20activity%2C%20young%20students%20with%20teacher%20exploring%20a%20green%20forest%2C%20warm%20sunlight%2C%20photorealistic%2C%20wide%20landscape&image_size=landscape_16_9'
const roomTwoCover = 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=traditional%20Chinese%20culture%20workshop%20for%20children%2C%20students%20making%20handicrafts%20at%20a%20wooden%20table%2C%20bright%20warm%20classroom%2C%20photorealistic%2C%20wide%20landscape&image_size=landscape_16_9'
const qrImage = 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=clean%20black%20and%20white%20abstract%20square%20QR-code-like%20geometric%20pattern%20on%20pure%20white%20background%2C%20high%20contrast%2C%20centered%2C%20no%20text&image_size=square'

type Modal = 'qr' | 'jump' | null
function ActivityTop({ title, onBack }: { title: string; onBack?: () => void }) { return <header className="activity-top">{onBack ? <button className="activity-back" onClick={onBack}><ArrowLeft size={22} /></button> : <div className="student"><span className="student-avatar">🦊</span><div><strong>侯贤</strong><small>二年级</small></div><ChevronRight size={15} /></div>}<h1>{title}</h1><div className="activity-actions"><MoreHorizontal size={24} /><span /><b>−</b><span /><CircleUserRound size={23} /></div></header> }
function QrModal({ onClose }: { onClose: () => void }) { return <div className="activity-modal-mask" onClick={onClose}><section className="activity-modal qr-modal" onClick={(event) => event.stopPropagation()}><button className="modal-close" onClick={onClose}><X size={21} /></button><h2>扫码进入直播间</h2><p>请使用微信扫一扫，进入活动直播间</p><img src={qrImage} alt="直播间二维码" /><a href={qrImage} download="活动直播间二维码.png"><Download size={17} /> 保存二维码</a></section></div> }
function JumpModal({ onClose }: { onClose: () => void }) { return <div className="activity-modal-mask" onClick={onClose}><section className="activity-modal jump-modal" onClick={(event) => event.stopPropagation()}><div className="jump-icon"><Play size={25} fill="currentColor" /></div><h2>即将进入直播间</h2><p>正在为你跳转至“传统文化体验直播间”</p><div><button className="modal-light" onClick={onClose}>取消</button><button className="modal-green" onClick={onClose}>立即进入</button></div></section></div> }
function ActivityHome({ onLive }: { onLive: () => void }) { return <main className="activity-app"><ActivityTop title="活动" /><div className="activity-scroll"><section className="activity-banner"><img src={waterfallCover} alt="自然研学瀑布风景" /></section><section className="participation"><nav><button>未参与</button><button className="selected">已参与</button></nav><article className="activity-card"><div className="activity-thumb"><span>已结束</span><img src={roomTwoCover} alt="监护人验收" /></div><div className="activity-info"><h2>监护人验收</h2><p>活动时间：04月19日-04月19日</p><div><button><Image size={16} />活动相册</button><button onClick={onLive}><Tv size={16} />活动直播</button><button className="work-btn">查看作品</button></div></div></article></section><div className="activity-tip">🎉 <span>新学期的选课开始了，快去投票吧～</span><ChevronRight size={20} /></div></div><footer className="activity-bottom"><button className="active"><CalendarDays />活动</button><button><BookOpen />学习</button><button><Tv />作品</button><button><MessageCircle /><i>5</i>消息</button><button><CircleUserRound />我的</button></footer></main> }
function LiveList({ onBack }: { onBack: () => void }) { const [modal, setModal] = useState<Modal>(null); return <main className="activity-app"><ActivityTop title="活动直播" onBack={onBack} /><div className="live-list"><div className="live-list-title"><span>活动直播间</span><small>共 2 场直播</small></div><article className="student-live-card"><div className="student-live-cover"><img src={roomOneCover} alt="自然研学探索直播间封面" /><span className="live-tag">直播中</span><button onClick={() => setModal('qr')}><Play size={16} fill="currentColor" />进入直播间</button></div><div className="student-live-info"><h2>自然研学探索直播间</h2><p>直播日期：2026年07月12日 09:00</p><span className="live-status live-now">正在直播</span></div></article><article className="student-live-card"><div className="student-live-cover"><img src={roomTwoCover} alt="传统文化体验直播间封面" /><span className="live-tag wait">待开播</span><button onClick={() => setModal('jump')}><Play size={16} fill="currentColor" />进入直播间</button></div><div className="student-live-info"><h2>传统文化体验直播间</h2><p>直播日期：2026年07月12日 14:30</p><span className="live-status">待开播</span></div></article></div>{modal === 'qr' && <QrModal onClose={() => setModal(null)} />}{modal === 'jump' && <JumpModal onClose={() => setModal(null)} />}</main> }
export default function StudentActivity() { const [page, setPage] = useState<'activity' | 'live'>('activity'); return page === 'activity' ? <ActivityHome onLive={() => setPage('live')} /> : <LiveList onBack={() => setPage('activity')} /> }
