import { ChangeEvent, useEffect, useState } from 'react'
import { ArrowLeft, CalendarClock, CheckCircle2, CircleDot, House, ImagePlus, MoreHorizontal, Play, Radio, X } from 'lucide-react'

interface LiveRoom { name: string; time: string; address: string; code: string; cover: string }
type View = 'plan' | 'history' | 'create'
type FormValues = LiveRoom
const initialForm: FormValues = { name: '', time: '', address: '', code: '', cover: '' }
const years = [2026, 2027, 2028]
const months = Array.from({ length: 12 }, (_, index) => index + 1)
const days = Array.from({ length: 31 }, (_, index) => index + 1)
const hours = Array.from({ length: 24 }, (_, index) => index)
const minutes = Array.from({ length: 12 }, (_, index) => index * 5)
const pad = (value: number) => String(value).padStart(2, '0')

function formatTime(value: string) { if (!value) return ''; const [date, clock] = value.split('T'); return `${date.replace(/-/g, '.')} ${clock}` }
function nowParts() { const now = new Date(); return { year: now.getFullYear(), month: now.getMonth() + 1, day: now.getDate(), hour: now.getHours(), minute: Math.ceil(now.getMinutes() / 5) * 5 % 60 } }

function TopBar({ onBack, createMode }: { onBack: () => void; createMode: boolean }) { return <header className="topbar"><div className="topbar-actions"><button className="chrome-button" aria-label="返回" onClick={onBack}><ArrowLeft size={25} strokeWidth={2.2} /></button><span className="chrome-divider" /><button className="chrome-button" aria-label="首页" onClick={onBack}><House size={22} strokeWidth={2.2} /></button></div><h1>{createMode ? '创建直播间' : '活动直播'}</h1><div className="system-actions"><MoreHorizontal size={26} strokeWidth={2.4} /><span className="system-divider" /><span className="mini-line" /><span className="system-divider" /><CircleDot size={25} strokeWidth={2.5} /></div></header> }
function EmptyState({ history, onCreate }: { history: boolean; onCreate: () => void }) { return <div className="empty-state"><div className="live-illustration" aria-hidden="true"><div className="signal signal-one" /><div className="signal signal-two" /><div className="signal signal-three" /><div className="person-head" /><div className="person-body" /><div className="person-arm left" /><div className="person-arm right" /><div className="box-front"><span /></div><div className="box-top" /></div><p>{history ? '暂无历史直播内容' : '直播计划内容为空'}</p>{!history && <button className="primary-button create-trigger" onClick={onCreate}>创建直播间</button>}</div> }
function RoomCard({ room }: { room: LiveRoom }) { return <article className="room-card"><img className="room-cover" src={room.cover} alt={`${room.name}直播封面`} /><div className="room-card-body"><strong>{room.name}</strong><p><CalendarClock size={14} /> {formatTime(room.time)}</p><div className="room-card-status"><span><Radio size={13} /> 待开播</span></div></div></article> }

function TimePicker({ value, onConfirm, onClose }: { value: string; onConfirm: (value: string) => void; onClose: () => void }) {
  const parsed = value ? value.split(/[-T:]/).map(Number) : []
  const [selected, setSelected] = useState(parsed.length ? { year: parsed[0], month: parsed[1], day: parsed[2], hour: parsed[3], minute: parsed[4] } : nowParts())
  const select = (key: keyof typeof selected) => (event: ChangeEvent<HTMLSelectElement>) => setSelected((current) => ({ ...current, [key]: Number(event.target.value) }))
  const options = (items: number[], selectedValue: number, onChange: (event: ChangeEvent<HTMLSelectElement>) => void, suffix: string) => <select value={selectedValue} onChange={onChange}>{items.map((item) => <option key={item} value={item}>{pad(item)}{suffix}</option>)}</select>
  return <div className="picker-mask" role="dialog" aria-modal="true" aria-label="选择开播时间" onMouseDown={onClose}><section className="time-picker" onMouseDown={(event) => event.stopPropagation()}><div className="picker-header"><button type="button" onClick={onClose}>取消</button><strong>选择开播时间</strong><button type="button" className="picker-confirm" onClick={() => onConfirm(`${selected.year}-${pad(selected.month)}-${pad(selected.day)}T${pad(selected.hour)}:${pad(selected.minute)}`)}>确定</button></div><div className="picker-value">{selected.year}年{pad(selected.month)}月{pad(selected.day)}日 {pad(selected.hour)}:{pad(selected.minute)}</div><div className="picker-wheels"><div>{options(years, selected.year, select('year'), '年')}</div><div>{options(months, selected.month, select('month'), '月')}</div><div>{options(days, selected.day, select('day'), '日')}</div><div>{options(hours, selected.hour, select('hour'), '时')}</div><div>{options(minutes, selected.minute, select('minute'), '分')}</div></div></section></div>
}

function CreateForm({ onBack, onSubmit }: { onBack: () => void; onSubmit: (room: LiveRoom) => void }) {
  const [form, setForm] = useState<FormValues>(initialForm)
  const [errors, setErrors] = useState<Record<string, string>>({})
  const [pickerOpen, setPickerOpen] = useState(false)
  function updateField(key: keyof FormValues, value: string) { setForm((current) => ({ ...current, [key]: value })); setErrors((current) => ({ ...current, [key]: '', stream: '' })) }
  function pickImage(key: 'cover' | 'code') { return (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => updateField(key, String(reader.result)); reader.readAsDataURL(file) } }
  function submit(event: React.FormEvent) { event.preventDefault(); const nextErrors: Record<string, string> = {}; if (!form.name.trim()) nextErrors.name = '请输入直播间名称'; if (!form.cover) nextErrors.cover = '请上传直播间封面'; if (!form.time) nextErrors.time = '请选择开播时间'; if (!form.address.trim() && !form.code) nextErrors.stream = '直播地址和直播二维码至少填写一项'; setErrors(nextErrors); if (!Object.keys(nextErrors).length) onSubmit({ ...form, name: form.name.trim(), address: form.address.trim() }) }
  const imageUpload = (key: 'cover' | 'code', label: string, hint: string, className: string) => <div className={className}>{form[key] ? <div className="image-preview"><img src={form[key]} alt={`已上传的${label}`} /><button type="button" onClick={() => updateField(key, '')} aria-label={`移除${label}`}><X size={15} /></button></div> : <label className="upload-placeholder"><ImagePlus size={24} /><span>上传{label}</span><input type="file" accept="image/*" onChange={pickImage(key)} /></label>}<p>{hint}</p></div>
  return <form className="create-page" onSubmit={submit} noValidate><div className="create-form-content"><section className="form-card"><div className="form-intro"><Radio size={21} /><span>直播基本信息</span></div><label className="field"><span>直播间名称 <b>*</b></span><input value={form.name} onChange={(event) => updateField('name', event.target.value)} placeholder="请输入直播间名称" />{errors.name && <em>{errors.name}</em>}</label><div className="field"><span>直播间封面 <b>*</b></span>{imageUpload('cover', '封面', '建议上传 16:9 的图片', 'cover-upload')}{errors.cover && <em>{errors.cover}</em>}</div><div className="field"><span>开播时间 <b>*</b></span><button type="button" className={`time-trigger ${form.time ? 'has-value' : ''}`} onClick={() => setPickerOpen(true)}><span>{form.time ? formatTime(form.time) : '请选择开播时间'}</span><CalendarClock size={18} /></button>{errors.time && <em>{errors.time}</em>}</div></section><section className="form-card stream-card"><div className="form-intro"><Play size={19} fill="currentColor" /><span>推流信息</span><small>至少填写一项</small></div><label className="field"><span>直播地址</span><input value={form.address} onChange={(event) => updateField('address', event.target.value)} placeholder="请输入直播推流地址" /></label><div className="field"><span>直播二维码</span>{imageUpload('code', '二维码', '请上传直播二维码图片', 'qr-upload')}</div>{errors.stream && <p className="stream-error">{errors.stream}</p>}</section></div><div className="form-actions"><button type="button" className="secondary-button" onClick={onBack}>取消</button><button type="submit" className="primary-button">创建直播间</button></div>{pickerOpen && <TimePicker value={form.time} onClose={() => setPickerOpen(false)} onConfirm={(value) => { updateField('time', value); setPickerOpen(false) }} />}</form>
}

export default function Home() { const [view, setView] = useState<View>('plan'); const [rooms, setRooms] = useState<LiveRoom[]>([]); const [notice, setNotice] = useState(''); useEffect(() => { if (!notice) return; const timer = window.setTimeout(() => setNotice(''), 2000); return () => window.clearTimeout(timer) }, [notice]); const openCreate = () => { setNotice(''); setView('create') }; const goPlan = () => setView('plan'); const createRoom = (room: LiveRoom) => { setRooms((current) => [room, ...current]); setView('plan'); setNotice('直播间已创建') }; const isCreate = view === 'create'; return <main className="app-shell"><div className="phone-frame"><TopBar createMode={isCreate} onBack={goPlan} />{isCreate ? <CreateForm onBack={goPlan} onSubmit={createRoom} /> : <><nav className="tabs"><button className={view === 'plan' ? 'active' : ''} onClick={goPlan}>直播计划</button><button className={view === 'history' ? 'active' : ''} onClick={() => setView('history')}>历史直播</button></nav><section className="content-area">{notice && <div className="toast"><CheckCircle2 size={17} />{notice}<button onClick={() => setNotice('')} aria-label="关闭提示"><X size={16} /></button></div>}{view === 'plan' && (rooms.length ? <div className="room-list">{rooms.map((room, index) => <RoomCard room={room} key={`${room.name}-${index}`} />)}<button className="compact-create" onClick={openCreate}>+ 创建直播间</button></div> : <EmptyState history={false} onCreate={openCreate} />)}{view === 'history' && <EmptyState history onCreate={openCreate} />}</section></>}</div></main> }
