import { BrowserRouter as Router, Navigate, Route, Routes, useLocation } from "react-router-dom";
import ClientSwitcher from "@/components/ClientSwitcher";
import BusinessRules from "@/components/BusinessRules";
import AdminLive from "@/pages/AdminLive";
import Home from "@/pages/Home";
import StudentActivity from "@/pages/StudentActivity";

function ClientPages() {
  const { pathname } = useLocation();
  return <div className={`app-route app-route--${pathname.slice(1) || 'org-mini'}`}><Routes><Route path="/org-mini" element={<div className="client-page client-page--org-mini"><Home /></div>} /><Route path="/org-web" element={<div className="client-page client-page--org-web"><AdminLive /></div>} /><Route path="/parent-mini" element={<div className="client-page client-page--parent-mini"><StudentActivity /></div>} /><Route path="*" element={<Navigate to="/org-mini" replace />} /></Routes><BusinessRules /><ClientSwitcher /></div>;
}

export default function App() {
  return <Router><ClientPages /></Router>;
}
